<template>
  <v-dialog v-model="open" persistent max-width="500px">
    <v-card>
      <v-card-title>
        <span class="header-3">Agregar Cervezas Tomadas</span>
        <v-spacer></v-spacer>
        <v-btn icon @click="handleClose">
          <v-icon>mdi-close</v-icon>
        </v-btn>
      </v-card-title>

      <v-card-text>
        <v-container>
          <v-row v-if="selectedClient">
            <v-col cols="12">
              <div class="client-info mb-4">
                <p class="header-4-alt">
                  {{ selectedClient.name }} {{ selectedClient.lastName }}
                </p>
                <p class="s-light-subtitles">
                  Nivel: {{ getLevel(selectedClient.level) }}
                </p>
                <p class="s-light-subtitles">
                  Cervezas tomadas actuales: {{ selectedClient.beersDrinked || 0 }}
                </p>
              </div>
            </v-col>

            <v-col cols="12">
              <v-text-field
                v-model.number="beersDrinkedToAdd"
                label="Cervezas tomadas a agregar"
                type="number"
                outlined
                dense
                min="1"
                prepend-icon="mdi-beer"
                hint="Cantidad de cervezas tomadas a sumar al contador"
                persistent-hint
              ></v-text-field>
            </v-col>

            <v-col cols="12" v-if="error">
              <v-alert type="error" dense>
                {{ error }}
              </v-alert>
            </v-col>
          </v-row>
        </v-container>
      </v-card-text>

      <v-card-actions>
        <v-spacer></v-spacer>
        <v-btn text @click="handleClose" :disabled="loading">
          Cancelar
        </v-btn>
        <v-btn
          color="primary"
          @click="addBenefits"
          :loading="loading"
          :disabled="!canSubmit"
        >
          Agregar
        </v-btn>
      </v-card-actions>
    </v-card>

    <v-overlay :value="loading">
      <v-progress-circular indeterminate size="64"></v-progress-circular>
    </v-overlay>
  </v-dialog>
</template>

<script>
import Api from "../../service/api";
import config from "../../config";

export default {
  name: "AddBenefits",
  props: {
    open: {
      type: Boolean,
      default: false
    },
    selectedClient: {
      type: Object,
      default: null
    },
    handleClose: {
      type: Function,
      required: true
    }
  },
  data() {
    return {
      beersDrinkedToAdd: 1,
      loading: false,
      error: ""
    };
  },
  computed: {
    canSubmit() {
      return (
        this.selectedClient &&
        this.beersDrinkedToAdd > 0 &&
        !this.loading
      );
    }
  },
  watch: {
    open(newVal) {
      if (newVal) {
        this.resetForm();
      }
    }
  },
  methods: {
    resetForm() {
      this.beersDrinkedToAdd = 1;
      this.error = "";
    },
    getLevel(level) {
      return config.cardLevels[level - 1];
    },
    async addBenefits() {
      if (!this.canSubmit) return;

      this.loading = true;
      this.error = "";

      try {
        const response = await Api().post("/rewards/addBenefitsToClient", {
          clientId: this.selectedClient._id,
          beersDrinked: this.beersDrinkedToAdd
        });

        if (response.data.confirmation === "success") {
          this.$emit("benefits-added", response.data.data);
          this.handleClose(true);
        } else {
          this.error =
            response.data.message || "Error al agregar cervezas";
        }
      } catch (err) {
        console.error("Error al agregar cervezas:", err);
        this.error = "Error de conexión. Intenta nuevamente.";
      } finally {
        this.loading = false;
      }
    }
  }
};
</script>

