// Catálogo de conceptos/tamaños de venta. Es el espejo de serve_options[]
// en el firmware (KRN_32/src/main.cpp) y de lo que registra el server:
// si se agrega un tamaño nuevo allá, hay que agregarlo aquí.
export const SERVE_SIZES = {
  TASTER: [
    { qty: ".06", label: "Taster 2oz" },
    { qty: ".142", label: "Taster 5oz" },
  ],
  PINT: [
    { qty: ".236", label: "Medio Vaso 8oz" },
    { qty: ".296", label: "Vaso 10oz" },
    { qty: ".473", label: "Vaso 16oz" },
  ],
  GROWLER: [
    { qty: "1", label: "Growler 32oz" },
    { qty: "2", label: "Growler 64oz" },
    { qty: "4", label: "Growler 128oz" },
  ],
};

// Cuenta cuántas ventas hay de cada tamaño de un concepto, en el orden del
// catálogo (alineado con las columnas que renderizan las vistas)
export function countByConcept(sales, concept) {
  return SERVE_SIZES[concept].map(
    (size) =>
      sales.filter((sale) => sale.concept === concept && sale.qty === size.qty)
        .length
  );
}

// Resumen por categoría de un conjunto de ventas (merma en litros)
export function countSalesByCategory(sales) {
  const merma = sales
    .filter((sale) => sale.concept === "MERMA")
    .reduce((total, sale) => total + parseFloat(sale.qty), 0);
  return {
    pints: countByConcept(sales, "PINT"),
    tasters: countByConcept(sales, "TASTER"),
    growlers: countByConcept(sales, "GROWLER"),
    merma,
  };
}
